namespace Domain.Models.Problems;

/// <summary>A particular compiler/runtime version, not just a language family.</summary>
public sealed class ProgrammingLanguage
{
    /// <summary>The language_id published by Judge0. Assigned explicitly, not generated by the database.</summary>
    public int Id { get; set; }
    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
    public required string Key { get; set; }
    public required string DisplayName { get; set; }
    public required string FileExtension { get; set; }
    public required string RuntimeVersion { get; set; }
    public bool IsEnabled { get; set; } = true;
}
